  [("Leer los parámetros", "En f(x) = −2x² + 5, ¿cuánto valen a y c, hacia dónde abre y cuál es el vértice?", ["a = −2 y c = 5.", "a es negativo: abre hacia abajo. El vértice es (0, 5) y 5 es el valor máximo."], "a = −2, c = 5; abre hacia abajo; vértice (0, 5)"),
   ("De la descripción a la fórmula", "Una curva abre hacia arriba, tiene vértice (0, −1) y tiene la misma abertura que x². ¿Cuál es su fórmula?", ["La misma abertura que x² significa a = 1.", "El vértice (0, −1) significa c = −1, así que f(x) = x² − 1."], "f(x) = x² − 1")],
