   T2("{F} ¿Cuál es el eje de simetría de g(x) = x² + 2?", "La recta x = 0", "La recta x = 2", "Sumar 2 sube la curva y deja el eje en x = 0."),
   Q("En m(x) = −x² + 4, el valor 4 es un", "máximo, porque la curva abre hacia abajo", "mínimo, porque la curva abre hacia abajo", "mínimo, porque la curva abre hacia arriba", "Con a negativo la curva abre hacia abajo y el vértice es el punto más alto."),
   Q("{F} ¿Qué modelo tiene una curva más cerrada que x², con el mismo vértice (0, 0)?", "k(x) = 3x²", "g(x) = x² + 2", "h(x) = x² − 3", "Solo k tiene a = 3, mayor que 1, y vértice en (0, 0)."),
   Q("Si c es negativo en a·x² + c, con a positivo, el vértice está", "por debajo del eje horizontal", "por encima del eje horizontal", "a la derecha del eje vertical", "El vértice (0, c) con c negativo queda bajo el eje horizontal."),
   ("=", "En f(x) = −x² + 4, ¿cuánto vale f(3)?", "-3*3+4", "Primero 3² = 9, con signo menos queda −9, y luego se suma 4."),
   ("=", "Evalúa 2x² − 5 en x = 0 para hallar la altura del vértice.", "2*0*0-5", "En x = 0 el término con x² desaparece y queda −5."),
   Q("Elige la fórmula de una curva que abre hacia abajo con vértice (0, 6).", "f(x) = −x² + 6", "f(x) = x² + 6", "f(x) = −x² − 6", "El signo menos delante de x² la abre hacia abajo y el +6 pone el vértice en (0, 6)."),
   T2("¿Tienen el mismo vértice x² − 3 y x² + 3?", "No: uno es (0, −3) y el otro (0, 3)", "Sí: los dos son (0, 0)", "El número que se suma o resta mueve el vértice hacia arriba o abajo."),
