   T2("{F} ¿D(x) = −2x² + 1 tiene un máximo o un mínimo?", "Un máximo: 1, porque abre hacia abajo", "Un mínimo: 1, porque abre hacia abajo", "Con a negativo el vértice es el punto más alto y vale 1."),
   Q("Un número fuera del cuadrado (x² + 5) y otro dentro (x − 4)²: ¿qué mueve cada uno?", "Fuera: arriba o abajo. Dentro: izquierda o derecha", "Fuera: izquierda o derecha. Dentro: arriba o abajo", "Los dos mueven la curva hacia arriba", "El número sumado fuera cambia las alturas y el de adentro cambia dónde está el cero."),
   ("=", "{F} Calcula D(2).", "-2*2*2+1", "Primero 2² = 4, luego −2 · 4 = −8 y al final se suma 1."),
   ("=", "{F} ¿Cuánto vale E(4) − C(4)?", "(4+1)*(4+1)-(4-4)*(4-4)", "E(4) = 25 y C(4) = 0, y se restan."),
   Q("Se necesita una curva que abra hacia arriba con vértice (6, 0). ¿Cuál sirve?", "(x − 6)²", "(x + 6)²", "x² + 6", "Para tener el vértice en x = 6, lo de adentro debe anularse en 6."),
   T2("{F} ¿Los modelos B y C tienen el mismo vértice?", "No: B tiene (0, 5) y C tiene (4, 0)", "Sí: los dos tienen el 4 y el 5", "B se mueve en vertical y C en horizontal, así que sus vértices son distintos."),
   Q("Un modelo da 9 en x = 0 y su vértice es (−3, 0). ¿Cuál es?", "(x + 3)²", "(x − 3)²", "x² + 9", "En x = 0 da 3² = 9 y su vértice está en x = −3."),
